    def __init__(self):
        self.emssim_factory = EmssimFactory.get_instance()

    def setup_ems(self, **kwargs):
        """Setup ems"""
        ip, password, port, prompt, user, diag_port = self._get_config_device_params(**kwargs)
        enb_id = kwargs.pop('enb_id', None)
        timeout = kwargs.pop('timeout', 180)
        bts_timeout = kwargs.pop('bts_timeout', 180)
        wait_tcp_connected = kwargs.pop('wait_tcp_connected', False)
        wait_connected = kwargs.pop('wait_connected', True)
        wait_discovered = kwargs.pop('wait_discovered', True)
        ne3s_activate = kwargs.pop('ne3s_activate', True)
        config_device = kwargs.pop('config_device')
        ne3s_user = get_config_variable(['ems', config_device, 'ne3s_user'])
        ne3s_password = get_config_variable(['ems', config_device, 'ne3s_password'])
        self.emssim_factory.ta_emss.setup_emss(timeout=timeout, bts_timeout=bts_timeout,
                                               wait_tcp_connected=wait_tcp_connected,
                                               wait_connected=wait_connected,
                                               wait_discovered=wait_discovered,
                                               enb_id=enb_id,
                                               host=ip, port=port,
                                               ne3s=ne3s_activate, reg_user=ne3s_user,
                                               reg_password=ne3s_password, **kwargs)
        self.enb_configuration_should_be_discovered(enb_id=enb_id)
        # subprocess.check_output('sudo ifconfig eth3:1 10.0.1.104 netmask 255.255.255.0',
        # shell=True)
        # subprocess.check_output('sudo ip link set dev eth3:1 up', shell=True)

    def configuration_manage(self, **kwargs):
        """Manage configuration"""
        operation = kwargs['operation']
        getattr(self, "_{}_configuration".format(operation.lower()))(**kwargs)

