    def perform_auto(self, *args, **kwargs):
        """Perform auto"""
        operation = kwargs.pop('operation')
        getattr(self, "_perform_auto_{}".format(operation.lower()))(*args, **kwargs)

    def perform_sw_update(self, **kwargs):
        """
        Performs a software update with activation.

        @param kwargs:
           package: Path to either the TargetBD xml file (unpacked version) or load package zip file (packed version)
           delay_after: sleep in seconds after software update completed (default 30)
           enb_id: BTS instance ID
           alias: Name of the execution context

        @return: NA


        Examples

        | Perform Software Update | /home/emssim/FL00_FSM3_9999_161128_034323_release_BTSSM_downloadable_wo_images.zip |

        | Perform Software Update | /home/emssim/LOADS/TargetBD_FL00_FSM3_9999_161128_034323.xml |
        """
        package = kwargs['package']
        delay_after = kwargs.pop('delay_after', 30)
        enb_id = kwargs.pop('enb_id', None)
        self.emssim_factory.ta_emss.perform_software_update(target=package, delay_after=delay_after, enb_id=enb_id)

    def verify_alarm(self, **kwargs):
        """Verify ems Alarms"""
        enb_id = kwargs.pop('enb_id', None)
        faultid = kwargs.get("faultid")
        # severity = kwargs.get("severity", None)
        should_exist = bool(kwargs.get("should_exist", True))
        occurrences = int(kwargs.get("occurrences", 1))
        faultid = int(faultid)

        alarms_list = self.emssim_factory.ta_emss.get_alarm_history(enb_id=enb_id)
        self._write_alarms_to_file('ems_alarms.json', alarms_list)
        self._verify_alarm_exists(alarms_list, faultid, occurrences, should_exist)
        return self.alarm_details

    def recover_ems_connection(self, **kwargs):
        """Recover ems connection"""
        enb_id = kwargs.pop('enb_id', None)
        return self.emssim_factory.ta_emss.recover_emss_connection(enb_id=enb_id)

    def run_ems_command(self, **kwargs):
        """Run ems command"""
        command = kwargs.pop('command')
        params = kwargs.pop('params', None)
        timeout = kwargs.pop('timeout', None)
        get_full_data = kwargs.pop('get_full_data', False)
        can_fail = kwargs.pop('can_fail', False)
        enb_id = kwargs.pop('enb_id', None)
        return self.emssim_factory.ta_emss.run_emssim_command(command=command,
                                                              params=params, timeout=timeout,
                                                              get_full_data=get_full_data,
                                                              can_fail=can_fail,
                                                              enb_id=enb_id)

    def wait_for_enb_discovery(self, **kwargs):
        """Wait for end discovery"""
        timeout = kwargs.pop('timeout', 120)
        delay = kwargs.pop('delay', 30)
        silent = kwargs.pop('silent', False)
        retry_sleep = kwargs.pop('retry_sleep', 30)
        enb_id = kwargs.pop('enb_id', None)
        return self.emssim_factory.ta_emss.wait_for_enb_discovery(timeout=timeout,
                                                                  delay=delay, silent=silent,
                                                                  retry_sleep=retry_sleep,
                                                                  enb_id=enb_id)

