    def get_enb_parameter_value(self, **kwargs):
        """
        Returns given parameter value

        @:param kwargs
            dist_name: MOC with ID
            bts_id (enb_id): BTS instance ID
            alias: User defined alias used in setup_emss

        @return: configured value

        Examples
        | get enb parameter value | LNCEL-1:inactivityTimer | bts_id=1   |
        """
        dist_name = kwargs['dist_name']
        dist_name = dist_name.rsplit("/")[-1].split(":")
        enb_id = kwargs.pop('enb_id', None)
        return self.emssim_factory.ta_emss.get_enb_parameter_value(moc_object=dist_name[0], parameter=dist_name[1],
                                                                   enb_id=enb_id)

