    def request_download(self, **kwargs):
        """
        Requests file download of specific file type.

        @param kwargs:
            path: Path to file on local filesystem (to be downloaded into eNodeB)
            file_name: Type of to-be-downloaded file. Supported file types:
                hwConfigurationFile, configurationPlanFile, logFile, swFile, licFile, measurementFile,
                rnwConfigurationPlanFile, signalingPlanFile, ipPlanFile, alarmFile, combinedSiteConfigurationPlanFile,
                allConfigurationPlanFile, locationLock, testResultFile, autoConfReport, connectedFapInfoFile,
                measurementPlanFile, rnwMetadataFile, topologyFile, atmPlanFile, subTopologyFile, togglingParFile,
                troubleShootingData, fapTmplFile, ipRangeFile, ipSecPlanFile, fapConfiguredPlanFile,
                fapActivatedPlanFile, fgwPlanFileWithoutMacroCells, fgwCertExpiryFile, fapCertExpiryFile,
                fapScanResultFile, fgwFcodesPlanFile, fgwInseePlanFile, fgwMacroDBPlanFile,
                fgwFapsIpSecConnFailureFile, fgwSecurityClonedHnbFile
            plan_id: Configuration change plan number [0..4294967295]
                In case of allConfigurationPlanFile(12) file type, this parameter should be identical to the id of
                attribute value inside the cmData element of to-be-downloaded XML file
            activate: (default 0)
            bts_id (enb_id): BTS instance ID
            alias - User defined alias used in setup_emss

        Examples

        | request download | /home/flexi57/UPLOADS/CUPL_BTSA_57.xml | allconfigurationplanfile | 3221225472 |

        """
        file_name = kwargs['file_name']
        path = kwargs['path']
        plan_id = kwargs['plan_id']
        activate = kwargs.pop('activate', 0)
        enb_id = kwargs.pop('enb_id', None)
        self.emssim_factory.ta_emss.request_download(path=path, file_name=file_name,
                                                     plan_id=plan_id, activate=activate,
                                                     enb_id=enb_id)

