    def plan(self, **kwargs):
        """
        Creates new plan needed for adding/deleting objects.

        @param kwargs:
            abandon_old: (bool, default=True) if set, keyword will destroy currently stored plan
            bts_id (enb_id): BTS instance ID

        Examples

        | create_new_plan |

        """
        operation = kwargs['operation']
        abandon_old = kwargs.pop('abandon_old', True)
        enb_id = kwargs.pop('enb_id', None)
        if operation.lower() == 'delete':
            return self.emssim_factory.ta_emss.destroy_existing_plan(enb_id=enb_id)
        if operation.lower() == 'create':
            self.emssim_factory.ta_emss.create_new_plan(abandon_old=abandon_old, enb_id=enb_id)

    def start_counters(self, **kwargs):
        """
        Returns value of the given object's counter.

        @param kwargs:
            object_name: Name of the object, e.g. DN:NE-LNBTS-88/FTM-1/ETHLK-0-1
            counter_id: counter ID, e.g. M51123C0
            bts_id (enb_id): BTS instance ID
        @return:
            counter value

        """
        enb_id = kwargs.pop('enb_id', None)
        pm_interval = kwargs.get("pm_interval", '15')
        self.emssim_factory.ta_emss.wait_for_next_interval(period=pm_interval, enb_id=enb_id)

    def pm_counters_stop_and_verify(self, **kwargs):
        """
        Returns value of the given object's counter.

        @param kwargs:
            object_name: Name of the object, e.g. DN:NE-LNBTS-88/FTM-1/ETHLK-0-1
            counter_id: counter ID, e.g. M51123C0
            bts_id (enb_id): BTS instance ID
        @return:
            counter value

        """
        object_name = kwargs['object_name']
        counter_id = kwargs['counter_id']
        enb_id = kwargs.pop('enb_id', None)
        logger.debug("First Interval Counters \n{}".format(str(EmsSim.initial_values)))
        EmsSim.final_values = self.emssim_factory.ta_emss.get_value_of_counter(object_name=object_name,
                                                                               counter_id=counter_id, enb_id=enb_id)
        logger.debug("Second Interval Counters \n{}".format(str(EmsSim.final_values)))
        error_flag = CounterVerification().perform_counter_evaluation(EmsSim.initial_values, EmsSim.final_values)
        json_filename = CounterVerification().save_analysis_to_file(analysis='EMSSIM', final_values=EmsSim.final_values)
        if error_flag:
            logger.debug("#### error_flag is {} and counter final value is {}".format(error_flag, EmsSim.final_values))
            raise Exception(
                "Atleast one counter validation failed, refer to {} ".format(json_filename))
        else:
            # return counters_ref["counters"][analysis]
            logger.debug("#### error_flag is {} and counter final value is {}".format(error_flag, EmsSim.final_values))
        return EmsSim.final_values

    def apply_planned_changes(self, **kwargs):
        """
        Sends and activates currently stored plan. Make sure all mandatory attributes are set, otherwise sending the
        plan will fail.

        @param kwargs:
            retry_limit: Number of retries if failed (default=3)
            retry_sleep: Time in seconds between retries (default=30)
            enb_id: BTS instance ID
            alias: User defined alias used in setup_emss
        @return:
            None
        """
        retry_limit = kwargs.get('retry_limit', 3)
        retry_sleep = kwargs.get('retry_sleep', 30)
        enb_id = kwargs.get('enb_id', None)
        self.emssim_factory.apply_planned_changes(retry_limit=retry_limit, retry_sleep=retry_sleep, enb_id=enb_id)

