    def _create_configuration(self, **kwargs):
        alias = kwargs.pop('alias', None)
        config = kwargs.pop('config')
        skip_ro = kwargs.pop('skip_ro', True)
        skip_np = kwargs.pop('skip_np', True)
        wait = kwargs.pop('wait', 60)
        wait_on_air = kwargs.pop('wait_on_air', True)
        enb_id = kwargs.pop('enb_id', None)
        self.emssim_factory.ta_emss.configure_and_wait(config, name=alias, skip_ro=skip_ro,
                                                       skip_np=skip_np, wait=wait,
                                                       wait_on_air=wait_on_air,
                                                       enb_id=enb_id, **kwargs)

    def _edit_configuration(self, **kwargs):
        self._create_configuration(**kwargs)

    def _delete_configuration(self, **kwargs):
        object_name = kwargs.pop('del_object_name')
        strict = kwargs.pop('strict', False)
        enb_id = kwargs.pop('enb_id', None)
        self.emssim_factory.ta_emss.configure_delete(moc=object_name, strict=strict, enb_id=enb_id)

    def _deconfigure_configuration(self, **kwargs):
        alias = kwargs.pop('alias', None)
        enb_id = kwargs.pop('enb_id', None)
        if alias:
            self.emssim_factory.ta_emss.deconfigure(name=alias, enb_id=enb_id)
        else:
            self.emssim_factory.ta_emss.deconfigure_all(enb_id=enb_id)

