    def _emss_proxy_clear_message_buffer(self, **kwargs):
        """
        Clears message buffer
        Parameters:
            (enb_id) (bts_id): BTS instance ID
            alias: User defined alias used in setup_emss
        """
        enb_id = kwargs.pop('end_id', None)
        alias = kwargs.pop('alias', 'default')
        self.emssim_factory.ta_emss.emss_proxy_clear_message_buffer(enb_id=enb_id, alias=alias)

    def _emss_proxy_get_message(self, **kwargs):
        """
        Gets message from BTS in proxy transparent mode
        Parameters:
            timeout: Maximum time to wait for a message (default=30)
            interval: Time between checks for messages (default=2)
            clear: Clear message buffer after get (default=True)
            output_string: Output message as string instead of complex structures (default=False)
            (enb_id) (bts_id): BTS instance ID
            alias: User defined alias used in setup_emss
        """
        timeout = kwargs.pop('timeout', 30)
        interval = kwargs.pop('interval', 2)
        clear = kwargs.pop('clear', True)
        output_string = kwargs.pop('output_string', False)
        enb_id = kwargs.pop('end_id', None)
        alias = kwargs.pop('alias', 'default')
        self.emssim_factory.ta_emss.emss_proxy_get_message(timeout=timeout, interval=interval,
                                                           clear=clear, output_string=output_string,
                                                           enb_id=enb_id, alias=alias)

    def _emss_proxy_send_message(self, **kwargs):
        """
        Sends message to BTS in proxy transparent mode
        Parameters:
            message: Message to send in the current Proxy plugin coding format
            clear: Clear old messages buffer before send (default=True)
            (enb_id) (bts_id): BTS instance ID
            alias: User defined alias used in setup_emss
        """
        message = kwargs['message']
        clear = kwargs.pop('clear', True)
        enb_id = kwargs.pop('end_id', None)
        alias = kwargs.pop('alias', 'default')
        self.emssim_factory.ta_emss.emss_proxy_send_message(message=message, clear=clear,
                                                            enb_id=enb_id, alias=alias)

    def _emss_proxy_ssl_cert(self, **kwargs):
        """
        Set TLS certificates and private key files
        Parameters:
            cert: Path to a file containing the users certificate in PEM format
            key: Path to a file containing the user’s private PEM-encoded key
            cacert: (optional) Path to a file containing PEM-encoded CA certificates
            (enb_id) (bts_id): BTS instance ID
            alias: User defined alias used in setup_emss
        """
        cert = kwargs.pop('cert', None)
        key = kwargs.pop('key', None)
        cacert = kwargs.pop('cacert', None)
        enb_id = kwargs.pop('end_id', None)
        alias = kwargs.pop('alias', 'default')
        self.emssim_factory.ta_emss.emss_proxy_ssl_cert(cert=cert, key=key, cacert=cacert,
                                                        enb_id=enb_id, alias=alias)

    def _emss_proxy_ssl_depth(self, **kwargs):
        """
        Set fbox maximum number of non-self-issued intermediate certificates that can follow the
        peer certificate in a valid certification path.
        If depth is 0 the PEER must be signed by the trusted ROOT-CA directly;
        if 1 the path can be PEER, CA, ROOT-CA;
        if 2 the path can be PEER, CA, CA, ROOT-CA, and so on.
        The default value is 10 (the same as apache2 default).

        Parameters:
            depth: integer
            (enb_id) (bts_id): BTS instance ID
            alias: User defined alias used in setup_emss
        """
        depth = kwargs.pop('depth', 10)
        enb_id = kwargs.pop('end_id', None)
        alias = kwargs.pop('alias', 'default')
        self.emssim_factory.ta_emss.emss_proxy_ssl_depth(depth=depth, enb_id=enb_id, alias=alias)

    def _emss_proxy_ssl_verify_none(self, **kwargs):
        """
        Disable eNodeB SSL certificates verification in fbox
        Parameters:
            (enb_id) (bts_id): BTS instance ID
            alias: User defined alias used in setup_emss
        """
        enb_id = kwargs.pop('end_id', None)
        alias = kwargs.pop('alias', 'default')
        self.emssim_factory.ta_emss.emss_proxy_ssl_verify_none(enb_id=enb_id, alias=alias)

    def _emss_proxy_ssl_verify_peer(self, **kwargs):
        """
        Enable eNodeB SSL certificates verification in fbox
        Parameters:
            (enb_id) (bts_id): BTS instance ID
            alias: User defined alias used in setup_emss
        """
        enb_id = kwargs.pop('end_id', None)
        alias = kwargs.pop('alias', 'default')
        self.emssim_factory.ta_emss.emss_proxy_ssl_verify_peer(enb_id=enb_id, alias=alias)

    def _emss_proxy_ssl_versions(self, **kwargs):
        """
        Set fbox supported TLS protocol versions
        Parameters:
            versions: string: Comma separated TLS versions or ‘clear’ for default behaviour
            (enb_id) (bts_id): BTS instance ID
            alias: User defined alias used in setup_emss
        """
        versions = kwargs['versions']
        enb_id = kwargs.pop('end_id', None)
        alias = kwargs.pop('alias', 'default')
        self.emssim_factory.ta_emss.emss_proxy_ssl_versions(versions=versions, enb_id=enb_id, alias=alias)

